            $varnameToken = $tokens[$index + 1];

            if (!$varnameToken->isGivenKind(T_STRING_VARNAME)) {
                continue;
            }

            $dollarCloseIndex = $this->findDollarCloseBraceIndex($tokens, $index);

            if (null === $dollarCloseIndex) {
                continue;
            }

            $tokenOfStringBeforeToken = $tokens[$index - 1];
            $stringContent = $tokenOfStringBeforeToken->getContent();

            if (str_ends_with($stringContent, '$') && !str_ends_with($stringContent, '\$')) {
                $newContent = substr($stringContent, 0, -1).'\$';
                $tokenOfStringBeforeToken = new Token([T_ENCAPSED_AND_WHITESPACE, $newContent]);
            }

            $overrideTokens = [
                $tokenOfStringBeforeToken,
                new Token([T_CURLY_OPEN, '{']),
                new Token([T_VARIABLE, '$'.$varnameToken->getContent()]),
            ];

            for ($offset = $index + 2; $offset < $dollarCloseIndex; ++$offset) {
                $overrideTokens[] = $tokens[$offset];
            }

            $overrideTokens[] = new Token([CT::T_CURLY_CLOSE, '}']);

            $tokens->overrideRange($index - 1, $dollarCloseIndex, $overrideTokens);
        }
    }

    private function findDollarCloseBraceIndex(Tokens $tokens, int $index): ?int
    {
        $squareBraceLevel = 0;

        for ($i = $index + 2, $count = \count($tokens); $i < $count; ++$i) {
            $token = $tokens[$i];

            if ($token->isGivenKind(CT::T_DOLLAR_CLOSE_CURLY_BRACES)) {
                return $i;
            }

            if ($token->equals('[')) {
                ++$squareBraceLevel;
            } elseif ($token->equals(']')) {
                --$squareBraceLevel;
            }
        }

        return null;
    }
}

